<?php
require_once __DIR__.'/../includes/functions.php';require_role(['super_admin','admin']);verify_csrf();$db=db();$error='';$isSuper=current_user()['role']==='super_admin';$roleOptions=$isSuper?['super_admin'=>'Super Admin','admin'=>'Admin','doctor'=>'Doctor','staff'=>'Staff']:['doctor'=>'Doctor','staff'=>'Staff'];
if($_SERVER['REQUEST_METHOD']==='POST'){$name=post_string('name',150);$email=strtolower(post_string('email',150));$phone=post_string('phone',50);$role=post_string('role',50);$pass=(string)($_POST['password']??'');$allowed=$isSuper?['super_admin','admin','doctor','staff']:['doctor','staff'];if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($role,$allowed,true)||strlen($pass)<8){$error='Enter valid details and a password of at least 8 characters.';}else{try{$db->beginTransaction();$q=$db->prepare('SELECT id FROM roles WHERE name=?');$q->execute([$role]);$rid=$q->fetchColumn();$s=$db->prepare("INSERT INTO users(role_id,name,email,password_hash,phone,status) VALUES(?,?,?,?,?,'active')");$s->execute([$rid,$name,$email,password_hash($pass,PASSWORD_DEFAULT),$phone]);$uid=(int)$db->lastInsertId();if($role==='doctor'){$dept=(int)($_POST['department_id']??0);$spec=post_string('specialization',150);$qual=post_string('qualification',200);$fee=(float)($_POST['fee']??0);if(!$dept||!$spec||!$qual)throw new RuntimeException('Doctor department, specialization and qualification are required.');$q=$db->prepare('INSERT INTO doctors(user_id,department_id,specialization,qualification,fee) VALUES(?,?,?,?,?)');$q->execute([$uid,$dept,$spec,$qual,$fee]);}if($role==='staff'){$q=$db->prepare('INSERT INTO staff_profiles(user_id,job_title) VALUES(?,?)');$q->execute([$uid,post_string('job_title',100)?:'Receptionist']);}$db->commit();audit((int)current_user()['id'],'USER_CREATED','users',(string)$uid,'Role: '.$role);flash('success','User account created.');redirect('users/index.php');}catch(Throwable $ex){if($db->inTransaction())$db->rollBack();$error=str_contains(strtolower($ex->getMessage()),'duplicate')?'This email is already in use.':$ex->getMessage();}}}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['toggle_id'])){$id=(int)$_POST['toggle_id'];$target=$db->prepare('SELECT r.name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=?');$target->execute([$id]);$targetRole=$target->fetchColumn();$canManage=$id!==(int)current_user()['id'] && $id!==1 && ($isSuper || in_array($targetRole,['doctor','staff'],true));if($canManage){$s=$db->prepare("UPDATE users SET status=IF(status='active','inactive','active') WHERE id=? AND id<>1");$s->execute([$id]);audit((int)current_user()['id'],'USER_STATUS_CHANGED','users',(string)$id,'Account status toggled');flash('success','Account status updated.');}else{flash('danger','You cannot change this account status.');}redirect('users/index.php');}
$users=$db->query('SELECT u.id,u.name,u.email,u.phone,u.status,u.created_at,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id ORDER BY u.created_at DESC')->fetchAll();$deps=$db->query("SELECT id,name FROM departments WHERE status='active' ORDER BY name")->fetchAll();$pageTitle='User management';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/page.php';page_heading('Administration','Users & roles','Create staff accounts and manage access status.');?>
<?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="row g-4"><div class="col-xl-4"><div class="card"><div class="card-header"><h2 class="section-title">Create account</h2></div><div class="card-body"><form method="post" data-disable-submit><?=csrf_field()?><div class="mb-3"><label class="form-label">Full name</label><input class="form-control" name="name" required maxlength="150"></div><div class="mb-3"><label class="form-label">Email</label><input class="form-control" type="email" name="email" required></div><div class="mb-3"><label class="form-label">Phone</label><input class="form-control" name="phone"></div><div class="mb-3"><label class="form-label">Role</label><select class="form-select" name="role" id="roleSelect" required><option value="">Choose role</option><?php foreach($roleOptions as $k=>$v):?><option value="<?=e($k)?>"><?=e($v)?></option><?php endforeach;?></select></div><div id="doctorFields" class="border rounded-3 p-3 mb-3 d-none"><div class="mb-2"><label class="form-label">Department</label><select class="form-select" name="department_id"><option value="">Choose</option><?php foreach($deps as $d):?><option value="<?=$d['id']?>"><?=e($d['name'])?></option><?php endforeach;?></select></div><div class="mb-2"><label class="form-label">Specialization</label><input class="form-control" name="specialization"></div><div class="mb-2"><label class="form-label">Qualification</label><input class="form-control" name="qualification"></div><div><label class="form-label">Consultation fee</label><input class="form-control" type="number" min="0" step="0.01" name="fee" value="0"></div></div><div class="mb-3"><label class="form-label">Temporary password</label><input class="form-control" type="password" name="password" minlength="8" required></div><button class="btn btn-primary w-100">Create user</button></form></div></div></div><div class="col-xl-8"><div class="card"><div class="card-header d-flex justify-content-between"><h2 class="section-title">All accounts</h2><span class="badge text-bg-light border"><?=count($users)?> users</span></div><div class="table-responsive"><table class="table"><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><strong><?=e($u['name'])?></strong><div class="small-muted"><?=e($u['email'])?></div></td><td><?=e(ucwords(str_replace('_',' ',$u['role_name'])))?></td><td><?=status_badge($u['status'])?></td><td><?=e(substr($u['created_at'],0,10))?></td><td><?php if((int)$u['id']!==(int)current_user()['id'] && (int)$u['id']!==1 && ($isSuper || in_array($u['role_name'],['doctor','staff'],true))):?><form method="post" class="d-inline" data-confirm="Change this account status?"><?=csrf_field()?><input type="hidden" name="toggle_id" value="<?=$u['id']?>"><button class="btn btn-sm btn-outline-secondary"><?= $u['status']==='active'?'Deactivate':'Activate'?></button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div></div><script>document.getElementById('roleSelect').addEventListener('change',e=>document.getElementById('doctorFields').classList.toggle('d-none',e.target.value!=='doctor'));</script><?php require __DIR__.'/../includes/footer.php';?>